static inline int get_data_buffer ( struct s3cmci_host * host , u32 * bytes , u32 * * pointer ) { struct scatterlist * sg ; if ( ( ! host -> mrq ) || ( ! host -> mrq -> data ) ) { return - EINVAL ; } if ( host -> pio_sgptr >= host -> mrq -> data -> sg_len ) { dbg ( host , dbg_debug , "no more buffers (%i/%i)\n" , host -> pio_sgptr , host -> mrq -> data -> sg_len ) ; return - EBUSY ; } sg = & host -> mrq -> data -> sg [ host -> pio_sgptr ] ; * bytes = sg -> length ; * pointer = sg_virt ( sg ) ; host -> pio_sgptr ++ ; dbg ( host , dbg_sg , "new buffer (%i/%i)\n" , host -> pio_sgptr , host -> mrq -> data -> sg_len ) ; return 0 ; } 